(()=>{'use strict';
const E=x=>(window.esc?esc(x):String(x??'')),money=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
function assistanceSummary(){if(currentTab!=='Ajudas'||!me?.assistance||document.querySelector('.sv4Help'))return;const root=document.getElementById('view'),items=Array.isArray(state.assistance)?state.assistance:[];if(!root)return;const now=new Date(),month=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`,m=items.filter(x=>String(x.date||'').startsWith(month)),total=m.reduce((n,x)=>n+(+x.amount||0),0),files=m.filter(x=>x.receiptPath).length;const box=document.createElement('div');box.className='sv4Help';box.innerHTML=`<div><span>Este mês</span><b>${m.length}</b><small>registros</small></div><div><span>Valor registrado</span><b>${money(total)}</b><small>acompanhamento</small></div><div><span>Comprovantes</span><b>${files}</b><small>anexados</small></div>`;root.prepend(box)}
function accessPolish(){if(currentTab!=='Acessos'||document.querySelector('.sv4AccessNote'))return;const root=document.getElementById('view');if(!root)return;const n=document.createElement('div');n.className='sv4AccessNote';n.innerHTML='<b>Acessos individuais</b><small>Altere apenas a senha necessária. As demais permanecem inalteradas.</small>';root.prepend(n)}
function mobileDetails(){document.querySelectorAll('.inlinePlan').forEach(p=>{if(p.dataset.sv4)return;p.dataset.sv4='1';p.querySelectorAll('textarea').forEach(t=>{t.setAttribute('enterkeyhint','done');t.style.resize='vertical'})});document.querySelectorAll('input[type="date"]').forEach(x=>x.setAttribute('inputmode','none'))}
function run(){try{assistanceSummary();accessPolish();mobileDetails()}catch(e){console.warn('safe bundle v4 skipped',e)}}
const old=window.renderTab;if(typeof old==='function')window.renderTab=function(){const r=old.apply(this,arguments);setTimeout(run,20);return r};new MutationObserver(()=>requestAnimationFrame(run)).observe(document.getElementById('view'),{childList:true,subtree:true});document.addEventListener('DOMContentLoaded',()=>setTimeout(run,30));
const s=document.createElement('style');s.textContent=`.sv4Help{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--ios-sep,var(--line));border-radius:16px;overflow:hidden;margin-bottom:14px}.sv4Help>div{background:var(--ios-card,#fff);padding:14px}.sv4Help span,.sv4Help b,.sv4Help small{display:block}.sv4Help span{font-size:10px;color:var(--mut)}.sv4Help b{font-size:17px;color:var(--teal);margin:3px 0}.sv4AccessNote{background:var(--ios-card,#fff);border-radius:15px;padding:14px 17px;margin-bottom:14px}.sv4AccessNote b,.sv4AccessNote small{display:block}.sv4AccessNote b{font-size:14px}.sv4AccessNote small{margin-top:3px}.inlinePlan textarea{min-height:86px}.mini,.primary,.scheduleToggle,.nav button{touch-action:manipulation}@media(max-width:600px){.sv4Help{grid-template-columns:1fr}.sv4Help>div{display:grid;grid-template-columns:1fr auto;align-items:center}.sv4Help small{grid-column:1/-1}.actionsRow .mini{min-height:42px}.primary{min-height:48px}}`;document.head.appendChild(s)})();